Explore all 1,000 greatest albums of all time unified in a single interactive visual soundstage.

albums = FileAttachment("top_1000_albums.csv").csv({ typed: true })

cleanData = albums.map(d =&gt; ({
  ...d,
  primary_genre: d.genres ? d.genres.split(",")[0].trim() : "other",
  decade: `${Math.floor(d.year / 10) * 10}s`
}))

// State for currently playing album on the turntable
mutable nowPlaying = cleanData[0]























viewof searchQuery = Inputs.text({
  placeholder: "Search 1,000 albums by artist, title, year, or genre..."
})

genresList = ["All", "rock", "pop", "folk", "electronica", "punk", "hip-hop", "soul", "jazz", "country", "metal"]
viewof selectedGenre = Inputs.select(genresList, {
  label: "Genre Filter",
  value: "All"
})























q = searchQuery.toLowerCase().trim()
matchingSet = new Set(
  cleanData
    .filter(d =&gt; {
      const matchGenre = selectedGenre === "All" || d.primary_genre === selectedGenre;
      const matchText = !q || 
        d.album.toLowerCase().includes(q) || 
        d.artist.toLowerCase().includes(q) || 
        String(d.year).includes(q) ||
        d.primary_genre.toLowerCase().includes(q);
      return matchGenre && matchText;
    })
    .map(d =&gt; d.rank)
)
















// Unified Soundstage Visual that integrates the turntable and all 1,000 album covers into one cohesive graphic
html`
&lt;div class="soundstage-visual"&gt;
  &lt;!-- Top Console: Integrated Vault Tabs & Active Turntable Deck --&gt;
  &lt;div class="soundstage-header"&gt;
    &lt;div class="deck-nav-bar" style="margin-bottom: 0.85rem; padding-bottom: 0.75rem;"&gt;
      &lt;span style="font-size: 0.75rem; font-weight: 700; color: #ffd166; text-transform: uppercase;"&gt;VAULT TABS:&lt;/span&gt;
      &lt;a href="index.qmd" class="deck-nav-pill active"&gt;🎵 1000-Cover Galaxy&lt;/a&gt;
      &lt;a href="compare.qmd" class="deck-nav-pill"&gt;⚖️ Cover Compare ↗&lt;/a&gt;
      &lt;a href="game.qmd" class="deck-nav-pill"&gt;🎮 Higher / Lower Game ↗&lt;/a&gt;
      &lt;a href="about.qmd" class="deck-nav-pill"&gt;ℹ️ About ↗&lt;/a&gt;
    &lt;/div&gt;

    &lt;div class="soundstage-deck-layout"&gt;
      &lt;!-- Mini Spinning Turntable Platter --&gt;
      &lt;div style="text-align: center;"&gt;
        &lt;div class="vinyl-record" style="width: 120px; height: 120px; margin: 0 auto; box-shadow: 0 0 20px rgba(0, 242, 254, 0.25);"&gt;
          &lt;div class="vinyl-label" style="width: 50px; height: 50px;"&gt;
            &lt;img src="${nowPlaying.image_url}" alt="${nowPlaying.album}" /&gt;
          &lt;/div&gt;
        &lt;/div&gt;
      &lt;/div&gt;

      &lt;!-- Active Album Details & Equalizer --&gt;
      &lt;div&gt;
        &lt;div style="font-size: 0.72rem; letter-spacing: 2px; color: #00f2fe; text-transform: uppercase; font-weight: 700;"&gt;
          ⚡ Active Turntable Spindle
        &lt;/div&gt;
        &lt;h3 style="margin: 0.2rem 0 0.1rem 0; font-size: 1.45rem; font-weight: 800; color: #fff; line-height: 1.2;"&gt;
          ${nowPlaying.album}
        &lt;/h3&gt;
        &lt;div style="font-size: 0.95rem; color: #cbd5e1;"&gt;
          ${nowPlaying.artist} &lt;span style="color: #ffd166;"&gt;(${nowPlaying.year})&lt;/span&gt;
        &lt;/div&gt;
        &lt;div style="margin-top: 0.35rem; font-size: 0.82rem; color: #94a3b8;"&gt;
          All-Time Rank: &lt;strong style="color: #00f2fe;"&gt;#${nowPlaying.rank}&lt;/strong&gt; of 1,000 &nbsp;|&nbsp;
          Rating: &lt;strong style="color: #ffd166;"&gt;⭐ ${nowPlaying.rating.toFixed(2)}&lt;/strong&gt; &nbsp;|&nbsp;
          Genre: &lt;strong style="color: #e2e8f0; text-transform: capitalize;"&gt;${nowPlaying.primary_genre}&lt;/strong&gt;
        &lt;/div&gt;

        &lt;div class="equalizer-wrap" style="height: 18px; margin: 0.5rem 0;"&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
          &lt;div class="eq-bar"&gt;&lt;/div&gt;
        &lt;/div&gt;

        &lt;div class="deck-controls" style="margin-top: 0.6rem;"&gt;
          &lt;button class="btn-neon" style="padding: 0.35rem 0.9rem; font-size: 0.8rem;" onclick=${() =&gt; {
            const randIndex = Math.floor(Math.random() * cleanData.length);
            mutable nowPlaying = cleanData[randIndex];
          }}&gt;
            🎲 Drop Needle (Random)
          &lt;/button&gt;

          &lt;a class="btn btn-outline-light btn-sm" style="font-size: 0.8rem; padding: 0.35rem 0.9rem; border-radius: 8px;" target="_blank" href="https://open.spotify.com/search/${encodeURIComponent(nowPlaying.artist + " " + nowPlaying.album)}"&gt;
            🎧 Listen on Spotify ↗
          &lt;/a&gt;

          &lt;span style="font-size: 0.8rem; color: #94a3b8; margin-left: auto; align-self: center;"&gt;
