  &lt;img src="${albumA_choice.image_url}" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; opacity: ${1 - crossfadeVal / 100}; transition: opacity 0.05s ease;" /&gt;

  &lt;!-- Album B layer --&gt;
